    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="root"></div>
    <script>
      const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      const phonePattern = /^\+?[0-9().\-\s]{7,20}$/;

      function FormField(config) {
        const describedBy = [config.helperId, config.errorId].filter(Boolean).join(" ");

        return `
          <div class="form-field">
            <label for="${config.id}">
              ${config.label}${config.required ? ' <span class="required-indicator" aria-hidden="true">*</span>' : ""}
            </label>
