              name="${config.name}"
              type="${config.type}"
              autocomplete="${config.autocomplete}"
              ${config.required ? "required" : ""}
              aria-required="${config.required ? "true" : "false"}"
              aria-describedby="${describedBy}"
            />
            ${
              config.helperText
                ? `<p class="helper-text" id="${config.helperId}">${config.helperText}</p>`
                : ""
            }
            <p class="error-message" id="${config.errorId}" aria-live="polite" hidden></p>
          </div>
        `;
      }

      function ContactForm() {
        return `
          <form id="contact-form" novalidate>
            ${FormField({
              id: "fullName",
              name: "fullName",
              label: "Full name",
              type: "text",
              autocomplete: "name",
              required: true,
              errorId: "fullName-error",
            })}
            ${FormField({
              id: "email",
              name: "email",
              label: "Email address",
              type: "email",
              autocomplete: "email",
              required: true,
              errorId: "email-error",
            })}
            ${FormField({
              id: "phone",
              name: "phone",
              label: "Phone number",
              type: "tel",
              autocomplete: "tel",
              helperText: "Optional. Use digits and may include spaces, parentheses, hyphens, or a leading +.",
              helperId: "phone-help",
              errorId: "phone-error",
            })}
            <button type="submit">Submit request</button>
            <p class="status-message" id="form-status" aria-live="polite"></p>
          </form>
        `;
      }

