        return `
          <main id="main-content">
            <section class="support-shell" aria-labelledby="support-heading">
              <p class="eyebrow">Support</p>
              <h1 id="support-heading">Get in touch with our support team</h1>
              <p class="intro">
                Share your contact details below and we&apos;ll follow up with the right next step.
              </p>
              ${ContactForm()}
            </section>
          </main>
        `;
      }

      function App() {
        return SupportPage();
      }

      document.getElementById("root").innerHTML = App();

      const form = document.getElementById("contact-form");
      const status = document.getElementById("form-status");
      const fields = {
        fullName: {
          input: document.getElementById("fullName"),
          error: document.getElementById("fullName-error"),
          validate(value) {
            if (!value.trim()) {
              return "Full name is required.";
            }

            return "";
          },
        },
        email: {
          input: document.getElementById("email"),
          error: document.getElementById("email-error"),
          validate(value) {
            const trimmed = value.trim();

            if (!trimmed) {
              return "Email address is required.";
            }

            if (!emailPattern.test(trimmed)) {
              return "Enter a valid email address.";
            }

            return "";
          },
        },
        phone: {
          input: document.getElementById("phone"),
          error: document.getElementById("phone-error"),
          validate(value) {
            const trimmed = value.trim();

            if (!trimmed) {
              return "";
            }

            if (!phonePattern.test(trimmed)) {
              return "Enter a valid phone number using digits and common separators.";
            }

            return "";
          },
        },
      };

